// Generate an input string for parsing. Ensure a valid, NUL-terminated C string.
// We exercise both: a well-formed dotted triplet and an arbitrary fuzz string.
unsigned int mode = *FUZZ_PARAM(unsigned int) % 2;
std::string fuzzStr = FUZZ_PARAM_STR();
std::string inputStr;
if (mode == 0) {
    // Construct a canonical dotted version string "A.B.C" with small ranges for safety.
    unsigned int A = *FUZZ_PARAM(unsigned int) % 1000;
    unsigned int B = *FUZZ_PARAM(unsigned int) % 1000;
    unsigned int C = *FUZZ_PARAM(unsigned int) % 1000;
    inputStr = std::to_string(A) + "." + std::to_string(B) + "." + std::to_string(C);
} else {
    // Use arbitrary fuzz data; c_str() guarantees NUL-termination.
    inputStr = fuzzStr;
}

// Call the target function with a non-null, NUL-terminated C string as required.
osgEarth::Version parsed = osgEarth::parseVersion(inputStr.c_str());

// Allocate an output object managed by the fuzzer runtime and copy the result.
osgEarth::Version *version = new osgEarth::Version();
*version = parsed;

// Optional metadata for downstream consumers (not required, but informative).
// We track whether the input was canonical (0) or fuzz (1).
FUZZ_SET_ATTR_INT(version, "input_mode", (int)mode);
FUZZ_SET_ATTR_STR(version, "input_str", inputStr.c_str());

// Validation summary: We ensured a non-null, NUL-terminated input string and produced
// a concrete osgEarth::Version* output initialized with the function's return value.

// Invoke the target function; this returns a pointer to a read-only, library-owned string.
const char *ver = osgEarthGetVersion();

// Defensive handling: the header does not guarantee non-null, so we only touch it if non-null.
if (ver) {
    // Read a byte to ensure the pointer is valid and avoid optimizing away the call.
    volatile char sink = ver[0];
    (void)sink;
}

// Validation summary: We called the function with no arguments, treated the return value
// as read-only and possibly null, and avoided taking ownership or writing to it.

// Invoke the target function; this returns a pointer to a read-only, library-owned string.
const char *sov = osgEarthGetSOVersion();

// Defensive handling: tolerate null; only probe if non-null.
if (sov) {
    volatile char sink = sov[0];
    (void)sink;
}

// Validation summary: The stub performs a safe, argument-free call and treats the
// returned pointer as optional and read-only without assuming ownership.

// Invoke the target function; this returns a pointer to a read-only, library-owned string.
const char *name = osgEarthGetLibraryName();

// Defensive handling: tolerate null; only probe if non-null.
if (name) {
    volatile char sink = name[0];
    (void)sink;
}

