import random
import string
from typing import List

# Generator for osgEarth::parseVersion input buffers.
# The fuzzer stub uses FUZZ_PARAM_STR to obtain the version string input.
# We therefore return bytes that represent a NUL-terminated C string containing
# interesting but valid version representations. We focus on well-formed inputs
# likely accepted by a typical dotted triplet parser: "<major>.<minor>.<patch>".
# We also include variety such as leading/trailing spaces, leading zeros,
# large values, and optional pre-release/build metadata (still valid strings,
# though the parser may or may not consume beyond digits).

MAX_LEN = 4096

_DIGITS = string.digits
_WS = " \t"


def _randint(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def _num_component(rng: random.Random) -> str:
    # Mix of ranges to exercise small, medium, and large version numbers
    mode = _randint(rng, 0, 4)
    if mode == 0:
        return str(_randint(rng, 0, 9))
    elif mode == 1:
        return str(_randint(rng, 10, 99))
    elif mode == 2:
        return str(_randint(rng, 100, 999))
    elif mode == 3:
        return str(_randint(rng, 1000, 9999))
    else:
        # Very large to test integer bounds in parsers
        return str(_randint(rng, 10000, 2_147_483_647))


def _with_leading_zeros(rng: random.Random, s: str) -> str:
    if s == "0":
        return s
    if _maybe(rng, 0.4):
        zeros = _randint(rng, 1, 4)
        return "0" * zeros + s
    return s


def _surround_ws(rng: random.Random, s: str) -> str:
    left = "".join(rng.choice(_WS) for _ in range(_randint(rng, 0, 3)))
    right = "".join(rng.choice(_WS) for _ in range(_randint(rng, 0, 3)))
    return left + s + right


def _build_metadata(rng: random.Random) -> str:
    # Optional prerelease/build metadata segments (semver-like);
    # parsers may ignore these but input remains a valid string.
    seg_chars = string.ascii_letters + string.digits + "-."
    def rand_ident(min_len: int, max_len: int) -> str:
        L = _randint(rng, min_len, max_len)
        return "".join(rng.choice(seg_chars) for _ in range(L))

    out = ""
    if _maybe(rng, 0.35):
        # prerelease: -alpha.1 etc.
        parts = [rand_ident(1, 6)]
        for _ in range(_randint(rng, 0, 2)):
            parts.append(rand_ident(1, 6))
        out += "-" + ".".join(parts)
    if _maybe(rng, 0.35):
        # build metadata: +build.11.e0f985a
        parts = [rand_ident(1, 6)]
        for _ in range(_randint(rng, 0, 2)):
            parts.append(rand_ident(1, 6))
        out += "+" + ".".join(parts)
    return out


def _build_version_string(rng: random.Random) -> str:
    # Construct a canonical dotted triplet with variations
    major = _with_leading_zeros(rng, _num_component(rng))
    minor = _with_leading_zeros(rng, _num_component(rng))
    patch = _with_leading_zeros(rng, _num_component(rng))

    sep = "."  # Stick to dot separators as expected by parseVersion
    core = sep.join([major, minor, patch])

    # Optional surrounding whitespace
    core = _surround_ws(rng, core)

    # Optional metadata (still valid as string; parser may stop at non-digits)
    core += _build_metadata(rng)

    # Optional trailing newline (commonly accepted when reading lines)
    if _maybe(rng, 0.2):
        core += rng.choice(["\n", "\r\n"]) 

    return core


def _bias_known_versions(rng: random.Random) -> str:
    # Include some likely real versions to exercise code paths comparing to constants
    known: List[str] = [
        "3.7.3",  # matches OSGEARTH_* in the header
        "3.7.0",
        "3.6.0",
        "3.0.0",
        "1.0.0",
        "0.0.0",
        "10.0.0",
    ]
    s = rng.choice(known)
    # Occasionally add whitespace or metadata to still be syntactically valid strings
    if _maybe(rng, 0.5):
        s = _surround_ws(rng, s)
    if _maybe(rng, 0.3):
        s += _build_metadata(rng)
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose among several templates of valid inputs
    mode = _randint(rng, 0, 4)
    if mode == 0:
        s = _bias_known_versions(rng)
    elif mode == 1:
        # Plain dotted triplet with small components
        A = str(_randint(rng, 0, 999))
        B = str(_randint(rng, 0, 999))
        C = str(_randint(rng, 0, 999))
        s = f"{A}.{B}.{C}"
        if _maybe(rng, 0.3):
            s = _surround_ws(rng, s)
    elif mode == 2:
        # Dotted triplet with leading zeros and metadata
        s = _build_version_string(rng)
    elif mode == 3:
        # Very large numeric components to test integer bounds, still valid digits
        A = str(_randint(rng, 1_000_000, 2_147_483_647))
        B = str(_randint(rng, 1_000_000, 2_147_483_647))
        C = str(_randint(rng, 1_000_000, 2_147_483_647))
        s = f"{A}.{B}.{C}"
    else:
        # Minimalistic edge cases that are still valid strings and often parsed:
        # single/double components extended to triplet by zeros
        # We still produce a triplet for validity but with small numbers
        parts = [str(_randint(rng, 0, 9)) for _ in range(3)]
        s = ".".join(parts)

    # Ensure NUL-terminated C string bytes for FUZZ_PARAM_STR consumption
    b = s.encode('utf-8', errors='strict')
    if len(b) + 1 > MAX_LEN:
        b = b[: MAX_LEN - 1]
    return b + b"\x00"
